import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 9
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )
    records = []
    try:
        for record in reader:
            if record and any(value.strip() for value in record):
                records.append(record)
    except csv.Error:
        pass

    def is_header(record: list[str]) -> bool:
        if len(record) != expected_width:
            return False
        values = [value.strip().lstrip("\ufeff") for value in record]
        identifier = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
        return (
            len(set(values)) == expected_width
            and all(identifier.fullmatch(value) for value in values)
        )

    header_index = next(
        (index for index, record in enumerate(records) if is_header(record)),
        None,
    )

    if header_index is None:
        header_index = next(
            (index for index, record in enumerate(records) if len(record) == expected_width),
            None,
        )

    if header_index is None:
        columns = [f"column_{index + 1}" for index in range(expected_width)]
        data_records = records
    else:
        columns = [value.lstrip("\ufeff") for value in records[header_index]]
        data_records = records[header_index + 1 :]

    rows = []
    for record in data_records:
        if len(record) < expected_width:
            record = record + [""] * (expected_width - len(record))
        elif len(record) > expected_width:
            record = record[: expected_width - 1] + [",".join(record[expected_width - 1 :])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
